import type { IRootState } from '@/core/global-store';
import { API_GATEWAY_BASE_URL } from '@/core/global-data/constants.data';
import type { EmployeeAttendanceType } from '@/features/humanResources/types/employeeAttendance.types';
import type { EmployeeApi } from './types';

export function displayValue(value: unknown): string {
    if (value === null || value === undefined || value === '') return '—';
    return String(value);
}

export function resolveImageUrl(path: string | null | undefined): string | null {
    if (!path) return null;
    if (typeof path === 'string' && path.startsWith('http')) return path;
    const base = (API_GATEWAY_BASE_URL || '').replace(/\/$/, '');
    const p = String(path).replace(/^\//, '');
    return base ? `${base}/${p}` : p;
}

export function idFromUnknown(v: unknown): number | undefined {
    if (typeof v === 'number' && !Number.isNaN(v)) return v;
    if (typeof v === 'string' && v !== '' && !Number.isNaN(Number(v))) return Number(v);
    return undefined;
}

export function workTypeLabel(employee: EmployeeApi): string {
    const raw = `${employee.employment_status ?? ''} ${employee.contract_type ?? ''}`.toLowerCase();
    if (raw.includes('full') || raw.includes('كلي') || raw.includes('كامل')) return 'كلي';
    if (raw.includes('part') || raw.includes('جزئ')) return 'جزئي';
    if (employee.employment_status) return displayValue(employee.employment_status);
    if (employee.contract_type) return displayValue(employee.contract_type);
    return '—';
}

export function resolvePerformancePercent(
    employee: EmployeeApi,
    summary: EmployeeAttendanceType['summary'] | undefined
): number {
    const a = Number(employee.current_month_attendance_average);
    if (Number.isFinite(a) && a >= 0) return Math.min(100, Math.max(0, Math.round(a)));
    if (summary && summary.total_days > 0) {
        return Math.min(100, Math.max(0, Math.round((summary.present / summary.total_days) * 100)));
    }
    return 60;
}

export function performanceBadgeLabel(percent: number): string {
    if (percent >= 75) return 'ممتاز';
    if (percent >= 50) return 'مقبول';
    return 'يحتاج تحسيناً';
}

export function flattenMePayload(me: Record<string, unknown> | null): Record<string, unknown> {
    if (!me) return {};
    const nested =
        typeof me.employee === 'object' && me.employee !== null && !Array.isArray(me.employee)
            ? (me.employee as Record<string, unknown>)
            : {};
    return { ...nested, ...me };
}

function coalesceNum(v: unknown, fallback: number): number {
    if (typeof v === 'number' && !Number.isNaN(v)) return v;
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
}

export function toDisplayEmployee(
    authUser: IRootState['auth']['user'],
    me: IRootState['auth']['me'],
    apiEmployee: EmployeeApi | null,
    cookieId?: number
): EmployeeApi | null {
    const auth = (authUser ?? null) as unknown as Record<string, unknown> | null;
    const flatMe = flattenMePayload(me);

    if (!auth && !apiEmployee && Object.keys(flatMe).length === 0) return null;

    const id =
        apiEmployee?.id ??
        idFromUnknown(flatMe.id) ??
        (typeof auth?.id === 'number' ? auth.id : idFromUnknown(auth?.id)) ??
        cookieId;
    if (id == null) return null;

    const raw: Record<string, unknown> = {
        ...(auth ?? {}),
        ...flatMe,
        ...((apiEmployee ?? {}) as Record<string, unknown>),
        id,
    };

    if (!raw.phone_number && typeof raw.phone === 'string') raw.phone_number = raw.phone;
    if (!raw.personal_image && raw.image != null) raw.personal_image = raw.image;

    delete raw.token;
    delete raw.email_verified_at;

    const pickStr = (...keys: string[]) => {
        for (const k of keys) {
            const v = raw[k];
            if (v !== undefined && v !== null && v !== '') return String(v);
        }
        return '';
    };

    const pickNum = (key: string, fallback = 0) => coalesceNum(raw[key], fallback);
    const optStr = (k: string) => {
        const v = raw[k];
        if (v === null || v === undefined || v === '') return undefined;
        return String(v);
    };

    return {
        id,
        name: pickStr('name'),
        email: pickStr('email'),
        phone_number: pickStr('phone_number', 'phone'),
        address: pickStr('address'),
        birth_date: pickStr('birth_date'),
        id_number: pickStr('id_number'),
        personal_image: (raw.personal_image ?? raw.image ?? null) as string | null,
        education_degree: pickStr('education_degree'),
        university: pickStr('university'),
        specialization: pickStr('specialization'),
        graduation_year: pickStr('graduation_year'),
        previous_experience: pickStr('previous_experience'),
        skills: pickStr('skills'),
        degree_certificate: (raw.degree_certificate ?? null) as string | null,
        branch_id: pickNum('branch_id'),
        shift_id: pickNum('shift_id'),
        employee_degree: (raw.employee_degree ?? null) as string | null,
        position: pickStr('position'),
        department: pickStr('department'),
        department_id: raw.department_id != null ? pickNum('department_id') : undefined,
        contract_type: pickStr('contract_type'),
        employment_status: (raw.employment_status ?? null) as string | null,
        attachment: (raw.attachment ?? null) as string | null,
        password: (raw.password ?? null) as string | null,
        created_at: pickStr('created_at'),
        updated_at: pickStr('updated_at'),
        current_month_attendance_average: pickNum('current_month_attendance_average'),
        position_name: raw.position_name as string | undefined,
        main_salary: raw.main_salary as string | number | undefined,
        last_position: raw.last_position as string | undefined,
        next_upgrade: raw.next_upgrade as string | undefined,
        branch_name: optStr('branch_name'),
        contract_start_date: optStr('contract_start_date'),
        contract_end_date: optStr('contract_end_date'),
        contract_sign_date: optStr('contract_sign_date'),
    };
}
